16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
41	    private static final Map<String, String> CITY_REGION = Map.of(
42	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "city")
49	    @NotEmpty
50	    private String city;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
55	    private String telephone;
56	
57	    @Column(name = "email")
58	    @Email
59	    private String email;
60	
61	    @Column(name = "postcode")
62	    private String postcode;
63	
64	    @Column(name = "registration_date")
65	    private LocalDate registrationDate;
66	
67	    @Column(name = "customer_code")
68	    private String customerCode;
69	
70	    @Column(name = "household_id")
71	    private String householdId;
72	
73	    @Column(name = "namesake_count")
74	    private Integer namesakeCount;
75	
76	    @Column(name = "membership_number")
77	    private String membershipNumber;
78	
79	    @Column(name = "bulk_signup_warning")
80	    private Boolean bulkSignupWarning;
81	
82	    @Column(name = "household_size")
83	    private Integer householdSize;
84	
85	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
86	    private Set<Pet> pets;
87	
88	    public String getAddress() {
89	        return this.address;
90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = address;
94	    }
95	
96	    public String getCity() {
97	        return this.city;
98	    }
99	
100	    public void setCity(String city) {
101	        this.city = city;
102	    }
103	
104	    /**
105	     * The canonical region derived from this owner's {@link #city} using the fixed
106	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
107	     * {@code Brisbane -> QLD}), or {@code "UNKNOWN"} when the city is not in the
108	     * table. Derived (not persisted); recomputed from the current city each call.
109	     *
110	     * @return the canonical region string, or {@code "UNKNOWN"}
111	     */
112	    @Transient
113	    public String getLocality() {
114	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
115	    }
116	
117	    /**
118	     * The owner's membership level, a number from 1 to 3 assigned at creation:
119	     * starting at 1, add 1 when an {@link #email} is present and add 1 when
120	     * {@link #namesakeCount} is 0, capped at 3 (level 4 is reserved for tenure).
121	     * Derived (not persisted); recomputed from the current fields each call.
122	     *
123	     * @return the membership level, from 1 to 3
124	     */
125	    @Transient
126	    public Integer getMembershipLevel() {
127	        int level = 1;
128	        if (this.email != null && !this.email.isBlank()) {
129	            level++;
130	        }
131	        if (this.namesakeCount != null && this.namesakeCount == 0) {
132	            level++;
133	        }
134	        return Math.min(level, 3);
135	    }
136	
137	    /**
138	     * The owner's preferred contact channel: {@code "EMAIL"} when an
139	     * {@link #email} is present, otherwise {@code "PHONE"}. Derived (not
140	     * persisted); recomputed from the current fields each call.
141	     *
142	     * @return {@code "EMAIL"} or {@code "PHONE"}
143	     */
144	    @Transient
145	    public String getContactPreference() {
146	        if (this.email != null && !this.email.isBlank()) {
147	            return "EMAIL";
148	        }
149	        return "PHONE";
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    public String getEmail() {
161	        return this.email;
162	    }
163	
164	    public void setEmail(String email) {
165	        this.email = email;
166	    }
167	
168	    public String getPostcode() {
169	        return this.postcode;
170	    }
171	
172	    public void setPostcode(String postcode) {
173	        this.postcode = postcode;
174	    }
175	
176	    public LocalDate getRegistrationDate() {
177	        return this.registrationDate;
178	    }
179	
180	    public void setRegistrationDate(LocalDate registrationDate) {
181	        this.registrationDate = registrationDate;
182	    }
183	
184	    public String getCustomerCode() {
185	        return this.customerCode;
186	    }
187	
188	    public void setCustomerCode(String customerCode) {
189	        this.customerCode = customerCode;
190	    }
191	
192	    public String getHouseholdId() {
193	        return this.householdId;
194	    }
195	
196	    public void setHouseholdId(String householdId) {
197	        this.householdId = householdId;
198	    }
199	
200	    public Integer getNamesakeCount() {
201	        return this.namesakeCount;
202	    }
203	
204	    public void setNamesakeCount(Integer namesakeCount) {
205	        this.namesakeCount = namesakeCount;
206	    }
207	
208	    public String getMembershipNumber() {
209	        return this.membershipNumber;
210	    }
211	
212	    public void setMembershipNumber(String membershipNumber) {
213	        this.membershipNumber = membershipNumber;
214	    }
215	
216	    public Boolean getBulkSignupWarning() {
217	        return this.bulkSignupWarning;
218	    }
219	
220	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
221	        this.bulkSignupWarning = bulkSignupWarning;
222	    }
223	
224	    public Integer getHouseholdSize() {
225	        return this.householdSize;
226	    }
227	
228	    public void setHouseholdSize(Integer householdSize) {
229	        this.householdSize = householdSize;
230	    }
231	
232	    /**
233	     * The single derived key used for duplicate detection, formed as
234	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
235	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
236	     * is the stored (lower-cased) email or the empty string when absent, and the
237	     * household component is the stored {@link #householdId} or the empty string
238	     * when the owner belongs to no household. Two owners are duplicates of each
239	     * other exactly when their whole identity keys are equal; because the telephone
240	     * is part of the key, two members of the same household with different
241	     * telephones have different identity keys. Derived (not persisted); recomputed
242	     * from the current fields each call.
243	     *
244	     * @return the owner's identity key
245	     */
246	    @Transient
247	    public String getIdentityKey() {
248	        String tel = this.telephone == null ? "" : this.telephone;
249	        String mail = this.email == null ? "" : this.email;
250	        String household = this.householdId == null ? "" : this.householdId;
251	        return tel + "|" + mail + "|" + household;
252	    }
253	
254	    /**
255	     * A stable, normalised key identifying this owner's household (same last name
256	     * and address). The last name is folded case- and whitespace-insensitively and
257	     * the address is reduced to its canonical form exactly as in
258	     * {@link #sameHouseholdAs(Owner)}, so two owners share a key iff they share a
259	     * household.
260	     *
261	     * @return the household key
262	     */
263	    public String householdKey() {
264	        return normalize(this.getLastName()) + "�" + normalizeAddress(this.address);
265	    }
266	
267	    /**
268	     * Whether this owner belongs to the same household as {@code other}: that is,
269	     * they share the same last name and address. The last name is compared
270	     * case-insensitively with runs of whitespace collapsed to a single space (and
271	     * surrounding whitespace trimmed); the address is compared in its canonical
272	     * normalised form (see {@link #normalizeAddress(String)}).
273	     *
274	     * @param other the owner to compare against
275	     * @return {@code true} if both owners share a household
276	     */
277	    public boolean sameHouseholdAs(Owner other) {
278	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
279	            && normalizeAddress(this.address).equals(normalizeAddress(other.address));
280	    }
281	
282	    /**
283	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
284	     * trim, collapse internal runs of whitespace to a single space and lower-case.
285	     */
286	    private static String normalize(String value) {
287	        if (value == null) {
288	            return "";
289	        }
290	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
291	    }
292	
293	    /**
294	     * Reduce an address to its canonical stored form: trim and collapse runs of
295	     * whitespace to a single space, upper-case, and expand common abbreviations
296	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
297	     * they appear as whole words. The result is what is stored, returned and used
298	     * for every household comparison; it is idempotent, so re-normalising an
299	     * already-normalised address leaves it unchanged.
300	     *
301	     * @param value the raw address (may be {@code null})
302	     * @return the normalised address, or the empty string if {@code value} is
303	     *         {@code null} or blank
304	     */
305	    public static String normalizeAddress(String value) {
306	        if (value == null) {
307	            return "";
308	        }
309	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
310	        if (collapsed.isEmpty()) {
311	            return "";
312	        }
313	        String[] tokens = collapsed.split(" ");
314	        for (int i = 0; i < tokens.length; i++) {
315	            tokens[i] = switch (tokens[i]) {
316	                case "ST" -> "STREET";
317	                case "RD" -> "ROAD";
318	                case "AVE" -> "AVENUE";
319	                default -> tokens[i];
320	            };
321	        }
322	        return String.join(" ", tokens);
323	    }
324	
325	    protected Set<Pet> getPetsInternal() {
326	        if (this.pets == null) {
327	            this.pets = new HashSet<>();
328	        }
329	        return this.pets;
330	    }
331	
332	    protected void setPetsInternal(Set<Pet> pets) {
333	        this.pets = pets;
334	    }
335	
336	    public List<Pet> getPets() {
337	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
338	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
339	        return Collections.unmodifiableList(sortedPets);
340	    }
341	
342	    public void setPets(List<Pet> pets) {
343	        this.pets = new HashSet<>(pets);
344	    }
345	
346	    public void addPet(Pet pet) {
347	        getPetsInternal().add(pet);
348	        pet.setOwner(this);
349	    }
350	
351	    /**
352	     * Return the Pet with the given name, or null if none found for this Owner.
353	     *
354	     * @param name to test
355	     * @return true if pet name is already in use
356	     */
357	    public Pet getPet(String name) {
358	        return getPet(name, false);
359	    }
360	
361	    /**
362	     * Return the Pet with the given name, or null if none found for this Owner.
363	     *
364	     * @param name to test
365	     * @return true if pet name is already in use
366	     */
367	    public Pet getPet(String name, boolean ignoreNew) {
368	        name = name.toLowerCase();
369	        for (Pet pet : getPetsInternal()) {
370	            if (!ignoreNew || !pet.isNew()) {
371	                String compName = pet.getName();
372	                compName = compName.toLowerCase();
373	                if (compName.equals(name)) {
374	                    return pet;
375	                }
376	            }
377	        }
378	        return null;
379	    }
380	
381	    public Pet getPet(Integer petId) {
382	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
383	    }
384	
385	    @Override
386	    public String toString() {
387	        return new ToStringCreator(this)
388	
389	            .append("id", this.getId())
390	            .append("new", this.isNew())
391	            .append("lastName", this.getLastName())
392	            .append("firstName", this.getFirstName())
393	            .append("address", this.address)
394	            .append("city", this.city)
395	            .append("telephone", this.telephone)
396	            .toString();
397	    }
398	}
